<script>
document.addEventListener('DOMContentLoaded',()=>{const actions=JSON.parse(document.getElementById('simulator-actions').textContent);const maxTurns={{ $maxTurns }};document.querySelectorAll('[data-scenario-builder]').forEach(form=>{const host=form.querySelector('[data-turns]');const existing=[...host.querySelectorAll('[data-existing-message]')].map(node=>node.dataset.existingMessage);host.textContent='';const add=(message='',selected='none',fixture={},confirmed=false)=>{const index=host.children.length;if(index>=maxTurns)return;const box=document.createElement('fieldset');const title=document.createElement('legend');title.textContent='Mensaje '+(index+1);box.append(title);const messageLabel=document.createElement('label');messageLabel.textContent='Mensaje del usuario';const area=document.createElement('textarea');area.name=`turns[${index}][message]`;area.maxLength=2000;area.required=true;area.value=message;messageLabel.append(area);box.append(messageLabel);const actionLabel=document.createElement('label');actionLabel.textContent='Acción esperada';const select=document.createElement('select');select.name=`turns[${index}][action_key]`;select.append(new Option('Ninguna acción','none'));actions.forEach(action=>select.append(new Option(action.name,action.key)));select.value=selected;actionLabel.append(select);box.append(actionLabel);const fields=document.createElement('div');box.append(fields);const render=()=>{fields.textContent='';const action=actions.find(item=>item.key===select.value);if(!action)return;action.properties.forEach((property,row)=>{const label=document.createElement('label');label.textContent=property.name+(property.required?' *':'');const input=document.createElement(property.type.includes('array')||property.type.includes('object')?'textarea':'input');input.name=`turns[${index}][fixture_fields][${row}][value]`;input.required=property.required;const hidden=document.createElement('input');hidden.type='hidden';hidden.name=`turns[${index}][fixture_fields][${row}][property]`;hidden.value=property.name;const value=fixture[property.name];input.value=value===undefined?'':(typeof value==='object'?JSON.stringify(value):String(value));if(property.type.includes('array')||property.type.includes('object'))input.placeholder='Lista o estructura de este campo';label.append(hidden,input);fields.append(label)});if(action.write){const label=document.createElement('label');const hidden=document.createElement('input');hidden.type='hidden';hidden.name=`turns[${index}][simulate_confirmation]`;hidden.value='0';const check=document.createElement('input');check.type='checkbox';check.name=`turns[${index}][simulate_confirmation]`;check.value='1';check.checked=confirmed;label.append(hidden,check,document.createTextNode(' Simular confirmación (solo continúa esta prueba)'));fields.append(label)}};select.addEventListener('change',()=>{fixture={};confirmed=false;render()});render();const remove=document.createElement('button');remove.type='button';remove.className='z-btn';remove.textContent='Quitar mensaje';remove.addEventListener('click',()=>{box.remove();[...host.children].forEach((child,i)=>child.querySelector('legend').textContent='Mensaje '+(i+1))});box.append(remove);host.append(box)};const selected=form.dataset.existingAction||'none';let fixture={};try{fixture=JSON.parse(form.dataset.existingFixture||'{}')}catch{}const confirmed=form.dataset.existingConfirmation==='1';(existing.length?existing:['']).forEach((message,index)=>add(message,index===0?selected:'none',index===0?fixture:{},index===0&&confirmed));form.querySelector('[data-add-turn]').addEventListener('click',()=>add())})});
</script>
